BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"SEC_ACCESS_GRANTS" (
    "ID" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "GRANTEE_USER_ID" NUMBER(10),
    "GRANTEE_ORG_UNIT_ID" NUMBER(10),
    "YPODEIGMA_ID" NUMBER(10) NOT NULL,
    "RESPONSIBLE_ORG_UNIT_ID" NUMBER(10) NOT NULL,
    "PERMISSIONS" NUMBER(10) NOT NULL,
    "INSERTED_AT" TIMESTAMP(3) NOT NULL,
    "INSERTED_BY_USER_ID" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_SEC_ACCESS_GRANTS" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_ACCESS_GRANTS_EXACTLY_ONE_GRANTEE" CHECK ((
    ("GRANTEE_USER_ID" IS NOT NULL AND "GRANTEE_ORG_UNIT_ID" IS NULL)
    OR
    ("GRANTEE_USER_ID" IS NULL AND "GRANTEE_ORG_UNIT_ID" IS NOT NULL)
)),
    CONSTRAINT "FK_SEC_ACCESS_GRANTS_REF_ORGANIZATIONAL_UNITS_GRANTEE_ORG_UNIT_ID" FOREIGN KEY ("GRANTEE_ORG_UNIT_ID") REFERENCES "REF_ORGANIZATIONAL_UNITS" ("ID"),
    CONSTRAINT "FK_SEC_ACCESS_GRANTS_REF_ORGANIZATIONAL_UNITS_RESPONSIBLE_ORG_UNIT_ID" FOREIGN KEY ("RESPONSIBLE_ORG_UNIT_ID") REFERENCES "REF_ORGANIZATIONAL_UNITS" ("ID"),
    CONSTRAINT "FK_SEC_ACCESS_GRANTS_REF_YPODEIGMATA_YPODEIGMA_ID" FOREIGN KEY ("YPODEIGMA_ID") REFERENCES "REF_YPODEIGMATA" ("ID"),
    CONSTRAINT "FK_SEC_ACCESS_GRANTS_SEC_USERS_GRANTEE_USER_ID" FOREIGN KEY ("GRANTEE_USER_ID") REFERENCES "SEC_USERS" ("ID"),
    CONSTRAINT "FK_SEC_ACCESS_GRANTS_SEC_USERS_INSERTED_BY_USER_ID" FOREIGN KEY ("INSERTED_BY_USER_ID") REFERENCES "SEC_USERS" ("ID")
)';
END;
/

